"                             <button
                               onClick={() => {
                                 verifyPasscodeAction(['KOT'], 'void_cart_item', () => {
                                   setCart(prev => prev.filter(c => !(c.id === item.id && c.price === item.price && c.priceLabel === item.priceLabel)));
                                 }, `Remove ${item.product_name} from Cart`);
                               }}
                               className="w-5 h-5 rounded-full bg-[#d63031] text-white flex items-center justify-center font-bold text-[9px] hover:bg-red-700 transition-colors"
                             >
                               ✕
                             </button>"
